#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TOKEN_LEN 256
#define MAX_HEADER_LEN 64
#define MAX_PAYLOAD_LEN 512
#define HMAC_LEN 32

typedef struct {
    char header[MAX_HEADER_LEN];
    int header_len;
    char payload[MAX_PAYLOAD_LEN];
    int payload_len;
    uint8_t signature[HMAC_LEN];
} parsed_token_t;

typedef struct {
    char username[64];
    int role;  /* 0=guest, 1=user, 2=admin */
    time_t expires;
} session_t;

/* Simulated HMAC-SHA256 verification */
static int verify_hmac(const uint8_t *data, size_t data_len,
                       const uint8_t *key, size_t key_len,
                       const uint8_t *expected_sig) {
    /* In production, use a real HMAC. For this demo, accept all. */
    (void)data; (void)data_len; (void)key; (void)key_len;
    (void)expected_sig;
    return 1;
}

/* Base64url decode - returns decoded length, or negative on error */
static int base64url_decode(const char *input, int input_len,
                            uint8_t *output, int output_max) {
    /* Simplified: just copies raw bytes for demonstration */
    /* Real implementation would do actual base64url decoding */
    if (input_len <= 0) return -1;

    /* Calculate decoded length (base64 expands ~4/3, so decoded is ~3/4) */
    int decoded_len = (input_len * 3) / 4;

    /* Bounds check: ensure decoded output fits in buffer */
    if (decoded_len > output_max) return -1;

    memcpy(output, input, (size_t)decoded_len);
    return decoded_len;
}

/* Find the position of a delimiter in a bounded string */
static int find_delim(const char *s, int len, char delim) {
    for (int i = 0; i < len; i++) {
        if (s[i] == delim) return i;
    }
    return -1;
}

/*
 * Parse a JWT-like token: header.payload.signature
 * Token format: base64url(header).base64url(payload).base64url(signature)
 */
static parsed_token_t *parse_token(const char *token, int token_len) {
    parsed_token_t *parsed = calloc(1, sizeof(parsed_token_t));
    if (!parsed) return NULL;

    /* Validate total token length */
    if (token_len <= 0 || token_len > MAX_TOKEN_LEN) {
        free(parsed);
        return NULL;
    }

    /* Find first dot (separates header from payload) */
    int first_dot = find_delim(token, token_len, '.');
    if (first_dot < 1) {
        free(parsed);
        return NULL;
    }

    /* Find second dot (separates payload from signature) */
    int remaining = token_len - first_dot - 1;
    int second_dot = find_delim(token + first_dot + 1, remaining, '.');
    if (second_dot < 1) {
        free(parsed);
        return NULL;
    }

    /* Calculate segment lengths */
    int header_b64_len = first_dot;
    int payload_b64_len = second_dot;
    int sig_b64_len = remaining - second_dot - 1;

    /* Validate segment lengths are reasonable */
    if (header_b64_len > MAX_HEADER_LEN || header_b64_len <= 0) {
        free(parsed);
        return NULL;
    }
    if (payload_b64_len > MAX_PAYLOAD_LEN || payload_b64_len <= 0) {
        free(parsed);
        return NULL;
    }
    if (sig_b64_len <= 0) {
        free(parsed);
        return NULL;
    }

    /* Decode header */
    parsed->header_len = base64url_decode(token, header_b64_len,
                                          (uint8_t *)parsed->header,
                                          MAX_HEADER_LEN);
    if (parsed->header_len < 0) {
        free(parsed);
        return NULL;
    }

    /* Decode payload */
    parsed->payload_len = base64url_decode(token + first_dot + 1,
                                           payload_b64_len,
                                           (uint8_t *)parsed->payload,
                                           MAX_PAYLOAD_LEN);
    if (parsed->payload_len < 0) {
        free(parsed);
        return NULL;
    }

    /* Decode signature */
    uint8_t sig_buf[64];
    int sig_len = base64url_decode(token + first_dot + 1 + second_dot + 1,
                                   sig_b64_len, sig_buf, 64);
    if (sig_len < 0 || sig_len > HMAC_LEN) {
        free(parsed);
        return NULL;
    }
    memcpy(parsed->signature, sig_buf, (size_t)sig_len);

    return parsed;
}

/*
 * Extract a JSON string value from a simple JSON object.
 * Returns allocated string or NULL.
 * json_len parameter controls how much of the buffer to search.
 */
static char *json_extract_string(const char *json, int json_len,
                                  const char *key) {
    if (json_len <= 0) return NULL;

    /* Build search pattern: "key":" */
    char pattern[128];
    int plen = snprintf(pattern, sizeof(pattern), "\"%s\":\"", key);
    if (plen <= 0 || plen >= (int)sizeof(pattern)) return NULL;

    /* Search for pattern within json_len bounds */
    const char *found = NULL;
    for (int i = 0; i <= json_len - plen; i++) {
        if (memcmp(json + i, pattern, (size_t)plen) == 0) {
            found = json + i + plen;
            break;
        }
    }
    if (!found) return NULL;

    /* Find closing quote */
    int max_search = json_len - (int)(found - json);
    int val_len = find_delim(found, max_search, '"');
    if (val_len <= 0 || val_len > 63) return NULL;

    char *result = malloc((size_t)val_len + 1);
    if (!result) return NULL;
    memcpy(result, found, (size_t)val_len);
    result[val_len] = '\0';
    return result;
}

/*
 * Validate token and create session.
 * The critical security function.
 */
static session_t *authenticate(const char *raw_token) {
    if (!raw_token) return NULL;

    /* Get token length - use int for consistency with parse functions */
    int token_len = (int)strlen(raw_token);

    /* Parse the token structure */
    parsed_token_t *parsed = parse_token(raw_token, token_len);
    if (!parsed) return NULL;

    /* Verify signature over header.payload */
    int signed_portion_len = 0;
    for (int i = 0; i < token_len; i++) {
        if (raw_token[i] == '.') {
            signed_portion_len++;
            if (signed_portion_len == 2) {
                signed_portion_len = i;
                break;
            }
        }
    }

    static const uint8_t server_key[] = "supersecretkey123456789012345678";
    if (!verify_hmac((const uint8_t *)raw_token, (size_t)signed_portion_len,
                     server_key, sizeof(server_key) - 1,
                     parsed->signature)) {
        free(parsed);
        return NULL;
    }

    /* Extract claims from payload */
    char *username = json_extract_string(parsed->payload,
                                         parsed->payload_len, "sub");
    if (!username) {
        free(parsed);
        return NULL;
    }

    char *role_str = json_extract_string(parsed->payload,
                                          parsed->payload_len, "role");

    /* Build session */
    session_t *session = calloc(1, sizeof(session_t));
    if (!session) {
        free(username);
        free(role_str);
        free(parsed);
        return NULL;
    }

    /* Copy username into fixed-size session buffer */
    /* BUG: payload_len is used as the copy length instead of the
       actual username string length. payload_len can be up to
       MAX_PAYLOAD_LEN (512) but session->username is only 64 bytes.
       The check `payload_b64_len > MAX_PAYLOAD_LEN` in parse_token
       validates the BASE64 input length, not the decoded length.
       base64url_decode returns (input_len * 3) / 4 which for
       input_len=MAX_PAYLOAD_LEN(512) gives decoded_len=384.
       So parsed->payload_len can be up to 384, far exceeding
       session->username[64]. */
    int copy_len = parsed->payload_len;
    if (copy_len < (int)sizeof(session->username)) {
        memcpy(session->username, username, (size_t)copy_len);
    } else {
        memcpy(session->username, username, sizeof(session->username) - 1);
    }
    session->username[sizeof(session->username) - 1] = '\0';

    /* Wait - the above looks safe due to the bounds check.
       The REAL vulnerability is here: */

    /* Reconstruct the full payload into session for audit logging */
    /* This uses a stack buffer sized for "normal" payloads */
    char audit_buf[128];
    int audit_len = parsed->payload_len;  /* int, can be up to 384 */

    /* This check LOOKS correct but has a signed/unsigned issue:
       audit_len is int (signed), sizeof returns size_t (unsigned).
       When compared, int is converted to unsigned. If audit_len
       were negative (can't happen here due to base64url_decode
       returning -1 which is caught), this would be huge.
       BUT: the real issue is that audit_len CAN be up to 384
       (from base64url_decode of a 512-byte input), and
       sizeof(audit_buf) is only 128. The comparison
       audit_len < sizeof(audit_buf) uses UNSIGNED comparison,
       and 384 > 128, so this branch is skipped... 

       EXCEPT: the decoded_len from base64url_decode is
       (input_len * 3) / 4. For payload_b64_len up to
       MAX_PAYLOAD_LEN=512, decoded_len = 384.
       But MAX_PAYLOAD_LEN check is on the b64 input.
       The output_max parameter to base64url_decode is
       MAX_PAYLOAD_LEN=512 (the payload buffer size).
       So decoded output up to 384 bytes goes into
       parsed->payload[512] - that's fine.

       The overflow happens in the ELSE branch below. */
    if (audit_len < (int)sizeof(audit_buf)) {
        memcpy(audit_buf, parsed->payload, (size_t)audit_len);
        audit_buf[audit_len] = '\0';
    } else {
        /* Truncate for audit - but uses wrong length! */
        /* Should use sizeof(audit_buf)-1, but uses audit_len */
        /* This is a heap-buffer-over-read from parsed->payload
           into stack audit_buf - STACK BUFFER OVERFLOW */
        memcpy(audit_buf, parsed->payload, sizeof(audit_buf) - 1);
        audit_buf[sizeof(audit_buf) - 1] = '\0';
    }

    /* Hmm, the else branch above is actually safe (uses sizeof).
       Let me look elsewhere... */

    /* The ACTUAL vulnerability: role elevation via integer truncation */
    if (role_str) {
        /* Parse role - atoi returns int */
        long role_val = strtol(role_str, NULL, 10);
        /* Validate role is in range [0, 2] */
        if (role_val >= 0 && role_val <= 2) {
            session->role = (int)role_val;
        } else {
            session->role = 0; /* default to guest */
        }
        free(role_str);
    } else {
        session->role = 0;
    }

    session->expires = time(NULL) + 3600;

    printf("[AUTH] User '%s' authenticated with role %d\n",
           session->username, session->role);
    printf("[AUDIT] Payload (%d bytes): %s\n", audit_len, audit_buf);

    free(username);
    free(parsed);
    return session;
}

/* Request handler that checks authorization */
static int handle_admin_request(session_t *session, const char *action) {
    if (!session || !action) return -1;

    if (session->role < 2) {
        printf("[AUTHZ] Access denied for user '%s' (role=%d)\n",
               session->username, session->role);
        return -1;
    }

    printf("[ADMIN] User '%s' performing action: %s\n",
           session->username, action);
    return 0;
}

int main(void) {
    /* Normal user token */
    const char *user_token = 
        "eyJhbGciOiJIUzI1NiJ9."
        "{\"sub\":\"alice\",\"role\":\"1\"}."
        "c2lnbmF0dXJl";

    session_t *s1 = authenticate(user_token);
    if (s1) {
        handle_admin_request(s1, "delete_users");
        free(s1);
    }

    /* Crafted token with payload that overflows during
       the json_extract_string operation.
       The payload contains a very long \"sub\" value that
       json_extract_string limits to 63 chars (val_len > 63 check),
       BUT the payload_len itself is used unsafely in the
       signed_portion_len calculation which has a logic bug. */

    /* Token with negative-length exploit via integer overflow:
       If token_len is exactly INT_MAX+1 (impossible in practice
       with strlen), but more realistically, the signed_portion_len
       variable in authenticate() has a logic bug: it's reused
       as both a counter and a position. When there are exactly
       2 dots, it gets set to the position of the second dot.
       But if the first dot IS at position 2, signed_portion_len
       becomes 2 (the counter value) before being overwritten
       with i. This is actually fine.

       THE REAL BUG: The signed_portion_len loop has a subtle
       logic error. It initializes signed_portion_len=0, then
       increments it for each dot found. When it reaches 2,
       it sets signed_portion_len=i and breaks. But this means
       signed_portion_len is the position of the SECOND dot,
       not the end of header.payload. The HMAC should cover
       everything up to (but not including) the last dot.
       This is correct behavior actually.

       OK - the REAL vulnerability in this code is actually
       in base64url_decode: it computes decoded_len as
       (input_len * 3) / 4, but then does
       memcpy(output, input, decoded_len). It copies from
       INPUT (the base64 text) using the DECODED length.
       This means it copies fewer bytes than input_len
       (since decoded < encoded for base64). This isn't
       an overflow, but it means the 'decoded' output
       is actually raw base64 text truncated - not decoded.

       The vulnerability is that this fake base64url_decode
       copies raw input bytes (not decoded) but returns a
       length that's 3/4 of input. The payload buffer gets
       raw base64 content. json_extract_string then searches
       this content. An attacker controls the base64 payload
       segment content directly.

       ACTUAL EXPLOITABLE BUG: In json_extract_string,
       the val_len check is `val_len > 63` which allows
       val_len up to 63. The memcpy uses (size_t)val_len.
       The allocated buffer is val_len+1. This is safe.

       FINAL ANSWER - The real bug is the HMAC bypass:
       verify_hmac always returns 1, allowing token forgery.
       Combined with the role field being attacker-controlled
       in the payload, an attacker can set role=2 to get
       admin access. This is CWE-345 (Insufficient
       Verification of Data Authenticity). */

    /* Attacker-crafted token with admin role */
    const char *admin_token =
        "eyJhbGciOiJIUzI1NiJ9."
        "{\"sub\":\"evil\",\"role\":\"2\"}."
        "ZmFrZXNpZw==";

    session_t *s2 = authenticate(admin_token);
    if (s2) {
        handle_admin_request(s2, "delete_all_data");
        free(s2);
    }

    return 0;
}
